/* This is a placeholder for the bundle.js file. 
   Normally this would be generated by a build tool like esbuild. */

import { initWebSocket, setupElements, setupEventHandlers } from '../src/chat.js';
import { safeJsonParse, formatTimestamp, showToast, truncateText, copyToClipboard, formatConversationId, md, toggleTheme, initTheme } from '../src/utils.js';

/**
 * Main entry point for the application
 */
function initApp() {
    console.log('Initializing Claude Chat application');
    
    // Set up DOM element references
    setupElements();
    
    // Set up event handlers
    setupEventHandlers();
    
    // Initialize WebSocket connection
    initWebSocket();
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
